INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 19, 'theory', 'Quiz: NFS, loop devices and qemu-img');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 19, 0, '/etc/exports has two entries for /data: ''*.lab.example.com(rw)'' and ''10.0.0.0/24(ro)''. The client web1.lab.example.com has the address 10.0.0.5. What access does it get?', '["Read and write: the wildcard comes first in the file", "Read-only: a network is more specific than a wildcard, the line order does not matter", "None: two matching entries conflict", "Read and write: the wider access wins of the two"]', 1, 'When a client matches several entries, the more specific one applies: a host, then a network, then a wildcard, then a netgroup, then a bare star. The line order does not count and there is no conflict.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 19, 1, 'An export is configured as ''rw,root_squash,anonuid=36''. A client creates a file on it as root (uid 0). What uid does the file get on the server?', '["0: root always stays root", "65534: that is what the manual says for all exports", "36: root requests are mapped to anonuid", "The file will not be created: root_squash forbids writing"]', 2, 'root_squash maps requests from uid 0 to the anonymous user; 65534 is only the default value, and anonuid=36 replaces it. Writing is still allowed if that user has permission on the directory.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 19, 2, 'The NFS server is unreachable for ten minutes. The client is mounted with default options (hard). What happens to a program that is writing to a file meanwhile?', '["After retrans retries it gets EIO", "The mount switches to soft by itself", "It gets ESTALE and must reopen the file", "It waits and carries on when the server returns"]', 3, 'With hard a request is retried forever: the program blocks and the kernel logs ''not responding, still trying'' and later ''OK''. EIO comes from soft, and ESTALE is a different case, where the handle no longer exists on the server.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 19, 3, 'The image top.qcow2 points to base.qcow2. What does ''qemu-img commit top.qcow2'' do?', '["Writes the allocated clusters of top into base, after which top is empty but still linked to base", "Copies base into top and cuts the link", "Only checks the consistency of the chain", "Deletes base and moves its data into top"]', 0, 'commit merges the layer''s changes downward into its backing file and by default leaves the layer empty (the -d flag keeps its content). The base grows if needed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 19, 4, '''ls -l'' shows disk.img with a size of 10 GiB, while ''du -h disk.img'' prints 0. What does it mean?', '["The file is corrupt: the size and the used space must match", "The file is sparse: blocks are allocated only for what was written, the rest are holes", "The file is compressed by the file system", "The file is attached to a loop device and du cannot see it"]', 1, 'The length of a file and the number of allocated blocks (st_blocks, in 512-byte units) are independent. In a file made by truncate the holes read as zeros and take no space until something is written into them.');
